def gen(rng):
    def fmt(arrs):
        return str(len(arrs)) + '\n' + '\n'.join('%d %s' % (len(x), ' '.join(map(str, x))) for x in arrs)
    tests = [fmt([[1]]), fmt([[3], [3], [3]]), fmt([[1, 2, 3], [4, 5, 6]]), fmt([[4, 5, 6], [1, 2, 3]]),
             fmt([[-5, 0, 7], [-6], [100, 200]]), fmt([[1, 1, 1], [1], [1, 1]])]
    for _ in range(25):
        k = rng.randint(1, 6)
        arrs = [sorted(rng.randint(-10, 10) for _ in range(rng.randint(1, 6))) for _ in range(k)]
        tests.append(fmt(arrs))

    def big(k, per, lo, hi):
        return fmt([sorted(rng.randint(lo, hi) for _ in range(per)) for _ in range(k)])
    tests.append(big(10000, 10, -10**9, 10**9))
    tests.append(big(1, 100000, -10**9, 10**9))
    tests.append(big(100, 1000, -10**9, 10**9))
    tests.append(big(5000, 20, -50, 50))
    return tests

